from collections import deque

def find_all_reachable_0s_within_distance(grid, start_points, max_dist):
    """Find all 0s within Manhattan distance of at most max_dist from any start point"""
    visited = set()
    queue = deque()

    for r, c in start_points:
        visited.add((r, c))
        queue.append((r, c, 0))  # (row, col, dist)

    reachable = set(start_points)

    while queue:
        r, c, d = queue.popleft()
        if d >= max_dist:
            continue

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            nd = d + 1

            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                    if nd <= max_dist:
                        visited.add((nr, nc))
                        reachable.add((nr, nc))
                        queue.append((nr, nc, nd))

    return reachable

