def decode_pattern_to_grid(pattern):
    """Decode a pattern tuple (value, dr, dc) to 3x3 grid"""
    grid = [[9 for _ in range(3)] for _ in range(3)]  # Default to 9
    center_r, center_c = 1, 1

    for val, dr, dc in pattern:
        if 0 <= center_r + dr < 3 and 0 <= center_c + dc < 3:
            grid[center_r + dr][center_c + dc] = val

    return grid

